const $=s=>document.querySelector(s),KEY='kelten-spurensuche-v1';
let state={station:0,task:0,results:{},draft:''},storageOK=true,selection=[],order=[],feedback=null,showResult=false;
try{const saved=JSON.parse(localStorage.getItem(KEY));if(saved&&typeof saved==='object'){state.station=Number.isInteger(saved.station)&&saved.station>=0&&saved.station<6?saved.station:0;state.task=Number.isInteger(saved.task)&&saved.task>=0&&saved.task<3?saved.task:0;state.draft=typeof saved.draft==='string'?saved.draft:'';if(saved.results&&typeof saved.results==='object')for(const [k,v]of Object.entries(saved.results)){if(/^[0-5]-[0-2]$/.test(k)&&v&&typeof v.first==='boolean'&&typeof v.correct==='boolean')state.results[k]={first:v.first,correct:v.correct};}}}catch{storageOK=false;}
function save(){try{localStorage.setItem(KEY,JSON.stringify(state));}catch{storageOK=false;}}
function esc(s){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}
const key=()=>`${state.station}-${state.task}`;
const current=()=>stations[state.station].tasks[state.task];
function start(s,t=0){state.station=s;state.task=t;showResult=false;selection=[];order=current().items?.map((_,i)=>i)||[];feedback=null;save();render();$('#game').focus({preventScroll:true});}
function sidebar(){const count=Object.values(state.results).filter(r=>r.correct).length,points=Object.values(state.results).filter(r=>r.first).length;
 $('#stations').innerHTML=stations.map((s,i)=>{const done=s.tasks.every((_,j)=>state.results[`${i}-${j}`]?.correct);return `<button class="station ${i===state.station&&!showResult?'active':''} ${done?'done':''}" data-station="${i}" ${i===state.station&&!showResult?'aria-current="step"':''}><span class="num">${done?'✓':String(i+1).padStart(2,'0')}</span>${s.title}</button>`;}).join('');
 document.querySelectorAll('[data-station]').forEach(b=>b.onclick=()=>start(+b.dataset.station));$('#progressText').textContent=`${count} / 18 gelöst`;$('#score').textContent=`${points} / 18 Ersttreffer`;$('#progress').value=count;
}
function render(){sidebar();if(showResult){renderResult();return;}const s=stations[state.station],t=current();
 $('#game').innerHTML=`<section class="mission"><div class="eyebrow">STATION ${String(state.station+1).padStart(2,'0')} / 06 · ${s.tag}</div><h2>${s.title}</h2><p>${s.intro}</p></section>${s.video?`<section class="video-panel"><div class="video-actions"><a href="${SRF}" target="_blank" rel="noopener">SRF-Beitrag ansehen ↗</a><button id="loadVideo" class="quiet">Video hier laden</button></div><p>Gesamtlänge: ca. 12 Minuten. Für die Aufgaben: 02:08–02:31, 07:09–07:39 und 10:31–11:21.</p><p class="video-note">Beim Laden wird eine Verbindung zu SRF hergestellt. Ohne Video hilft dir die Wissenskarte unten.</p><div id="video"></div></section>`:''}<div class="pills" aria-label="Aufgabe wählen">${s.tasks.map((_,i)=>`<button class="pill ${i===state.task?'active':''} ${state.results[`${state.station}-${i}`]?.correct?'done':''}" data-task="${i}" ${i===state.task?'aria-current="step"':''}>${i+1}. Spur</button>`).join('')}</div><section class="card"><div class="taskmeta">${{choice:'EINE ANTWORT',multi:'MEHRERE ANTWORTEN',match:'ZUORDNEN',order:'REIHENFOLGE'}[t.type]} · AUFGABE ${state.station*3+state.task+1} / 18</div><h3>${t.q}</h3><div id="input"></div><div id="feedback" aria-live="polite"></div><div class="actions"><button id="check" class="primary">Antwort prüfen</button><button id="next" class="quiet" ${state.results[key()]?.correct?'':'hidden'}>${state.task===2&&state.station===5?'Zur Auswertung':'Nächste Spur →'}</button></div><details><summary>Wissenskarte öffnen</summary><p>${s.note}</p><p class="source-line">${s.source}</p></details></section>${!storageOK?'<p class="storage-warning">Dein Browser erlaubt kein Speichern. Du kannst spielen, aber der Fortschritt bleibt nur bis zum Schliessen dieser Seite erhalten.</p>':''}`;
 document.querySelectorAll('[data-task]').forEach(b=>b.onclick=()=>start(state.station,+b.dataset.task));if(s.video)$('#loadVideo').onclick=()=>{$('#video').innerHTML='<iframe title="SRF: Die Kelten und die Römer" src="https://www.srf.ch/play/embed?urn=urn:srf:video:3da18acb-1a0a-4cab-97ce-0b0fb3f4f4e4" allow="fullscreen" allowfullscreen></iframe>';$('#loadVideo').disabled=true;};
 renderInput();$('#check').onclick=check;$('#next').onclick=next;
}
function renderInput(){const t=current();if(t.type==='choice'||t.type==='multi'){$('#input').innerHTML=`<div class="options">${t.options.map((o,i)=>`<button class="option ${selection.includes(i)?'selected':''}" data-option="${i}" aria-pressed="${selection.includes(i)}"><span class="marker">${selection.includes(i)?'✓':String.fromCharCode(65+i)}</span><span>${o}</span></button>`).join('')}</div>`;document.querySelectorAll('[data-option]').forEach(b=>b.onclick=()=>{const i=+b.dataset.option;selection=t.type==='choice'?[i]:selection.includes(i)?selection.filter(n=>n!==i):[...selection,i];clearFeedback();renderInput();});}
 else if(t.type==='match'){$('#input').innerHTML=t.items.map((o,i)=>`<label class="match-row"><span>${o}</span><select data-match="${i}" aria-label="Zuordnung: ${o}"><option value="">Bitte wählen</option>${t.categories.map((c,j)=>`<option value="${j}" ${selection[i]===j?'selected':''}>${c}</option>`).join('')}</select></label>`).join('');document.querySelectorAll('[data-match]').forEach(b=>b.onchange=()=>{selection[+b.dataset.match]=b.value===''?null:+b.value;clearFeedback();});}
 else{$('#input').innerHTML='<p class="small">Verschiebe mit den Pfeiltasten-Schaltflächen. Oben steht das älteste Ereignis.</p>'+order.map((id,pos)=>`<div class="order-row"><span class="small">${pos+1}</span><span class="rowtext">${t.items[id]}</span><div class="move"><button data-move="${pos}" data-dir="-1" ${pos===0?'disabled':''} aria-label="${esc(t.items[id])} nach oben">↑</button><button data-move="${pos}" data-dir="1" ${pos===order.length-1?'disabled':''} aria-label="${esc(t.items[id])} nach unten">↓</button></div></div>`).join('');document.querySelectorAll('[data-move]').forEach(b=>b.onclick=()=>{const i=+b.dataset.move,j=i+(+b.dataset.dir);[order[i],order[j]]=[order[j],order[i]];clearFeedback();renderInput();const target=document.querySelector(`[data-move="${j}"][data-dir="${b.dataset.dir}"]:not(:disabled)`)||document.querySelector(`[data-move="${j}"] button`)||document.querySelector(`[data-move="${j}"]:not(:disabled)`);target?.focus();});}}
function clearFeedback(){feedback=null;$('#feedback').innerHTML='';$('#check').disabled=false;}
function check(){const t=current();if((['choice','multi'].includes(t.type)&&!selection.length)||(t.type==='match'&&!t.items.every((_,i)=>Number.isInteger(selection[i])))){$('#feedback').innerHTML='<p role="status">Bitte beantworte zuerst alle Teile dieser Aufgabe.</p>';return;}
 const actual=t.type==='order'?order:t.type==='multi'?[...selection].sort((a,b)=>a-b):t.type==='choice'?selection[0]:selection;
 const correct=JSON.stringify(actual)===JSON.stringify(t.answer),prev=state.results[key()];state.results[key()]={first:prev?prev.first:correct,correct:!!prev?.correct||correct};save();sidebar();
 $('#feedback').innerHTML=`<div class="feedback ${correct?'':'wrong'}"><strong>${correct?'Spur entschlüsselt!':'Noch nicht ganz.'}</strong><p>${t.why}</p>${correct?'':'<p>Nutze den Hinweis und ändere deine Antwort. Beim nächsten Versuch kannst du die Spur abschliessen.</p>'}</div>`;$('#check').disabled=true;$('#next').hidden=!state.results[key()].correct;
 document.querySelector(`[data-task="${state.task}"]`)?.classList.toggle('done',state.results[key()].correct);
}
function next(){if(state.task<2)start(state.station,state.task+1);else if(state.station<5)start(state.station+1);else{showResult=true;render();$('#game').focus();}}
function renderResult(){const points=Object.values(state.results).filter(r=>r.first).length,solved=Object.values(state.results).filter(r=>r.correct).length;
 const missing=stations.flatMap((s,i)=>s.tasks.map((t,j)=>({s:i,t:j,title:s.title,result:state.results[`${i}-${j}`]}))).filter(x=>!x.result?.correct);
 $('#game').innerHTML=`<section class="mission"><div class="eyebrow">DEIN EXPEDITIONSBERICHT</div><h2>${solved===18?'Die Vitrine ist bereit.':'Es gibt noch Spuren zu entdecken.'}</h2><div class="result-number">${solved}<span style="font-size:26px"> / 18</span></div><p>${points} Antworten waren beim ersten Versuch richtig. ${solved===18?'Du hast alle Aufgaben gelöst. Formuliere jetzt dein eigenes Urteil.':'Kehre zu den offenen Aufgaben zurück.'}</p></section>${missing.length?`<div class="review-list">${missing.map(x=>`<button class="quiet" data-review="${x.s},${x.t}">${x.title} · Spur ${x.t+1} bearbeiten →</button>`).join('')}</div>`:''}<section class="card final-card"><div class="taskmeta">TRANSFER · DEIN EIGENES URTEIL</div><h3>Waren die Kelten «nur wilde Barbaren»?</h3><p>Schreibe eine Museumsbeschriftung in 3–5 Sätzen. Nenne zwei konkrete Belege und eine Grenze unseres Wissens.</p><label for="judgment" class="small">Dein Ausstellungstext · wird nur lokal gespeichert</label><textarea id="judgment" placeholder="Das pauschale Bild greift zu kurz, denn …">${esc(state.draft)}</textarea><details class="rubric"><summary>Selbstcheck und Beispiel</summary><p>Dein Text wird nicht automatisch benotet. Prüfe ihn anhand dieser Kriterien:</p><label><input type="checkbox">Ich nenne mindestens zwei konkrete Belege.</label><label><input type="checkbox">Ich unterscheide Funde, Deutungen und fremde Perspektiven.</label><label><input type="checkbox">Ich vermeide pauschale Aussagen über alle Kelten.</label><p><strong>Mögliche Antwort:</strong> Keltische Gruppen lebten nicht nur vom Krieg. Eisenwerkzeuge und Münzen belegen handwerkliche Spezialisierung und wirtschaftlichen Austausch. Befestigte Siedlungen erfüllten mehrere zentrale Funktionen. Römische und griechische Texte zeigen oft einen Blick von aussen; auch archäologische Funde lassen nicht jede Frage eindeutig beantworten.</p></details><details><summary>Weiterdenken: Erinnerung und «Hochkultur»</summary><p>Die Präsentation erinnert über Asterix an die Kelten. Welche Bilder werden dabei verstärkt? Vergleiche Unterhaltung mit einem Museumsbeitrag.</p><p>Städte, Arbeitsteilung, Kunst und Handel sprechen für eine komplexe Gesellschaft. Fehlende eigene erhaltene Geschichtswerke bedeuten weder fehlenden Schriftgebrauch noch kulturelle Minderwertigkeit. Diskutiert, was der Begriff «Hochkultur» sichtbar macht und welche Wertungen er mitbringt.</p></details><div class="actions"><button class="primary" id="download">Bericht herunterladen</button><button class="quiet" id="print">Drucken</button><button class="quiet" id="again">Stationen wiederholen</button></div></section>`;
 $('#judgment').oninput=e=>{state.draft=e.target.value;save();};$('#print').onclick=()=>window.print();$('#again').onclick=()=>start(0);document.querySelectorAll('[data-review]').forEach(b=>b.onclick=()=>start(...b.dataset.review.split(',').map(Number)));
 $('#download').onclick=()=>{const report=`DIE KELTEN – EXPEDITIONSBERICHT\n\nGelöst: ${solved}/18\nBeim ersten Versuch richtig: ${points}/18\n\n${stations.map((s,i)=>s.title+': '+s.tasks.filter((_,j)=>state.results[`${i}-${j}`]?.correct).length+'/3 gelöst').join('\n')}\n\nMEIN MUSEUMSURTEIL\n${state.draft||'(Noch kein Text verfasst.)'}\n\nGrundlagen: Die Kelten.docx; PPP_Kelten (1).pptx; SRF: Die Kelten und die Römer.\n${SRF}`;const url=URL.createObjectURL(new Blob([report],{type:'text/plain;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='Kelten-Expeditionsbericht.txt';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};
}
$('#sourceContent').innerHTML=`<p><strong>Spielregeln:</strong> Entschlüssle 18 Spuren in sechs frei zugänglichen Stationen. Jede richtige Lösung schliesst eine Spur ab. Nur der erste Versuch zählt als Ersttreffer; Wiederholungen sind unbegrenzt. Wissenskarten stehen jederzeit zur Verfügung. Es gibt keinen Timer.</p><ul><li><strong>Die Kelten.docx:</strong> Sachtext aus Notz/Frey (Hg.), <em>Geschichte fürs Gymnasium. Steinzeit bis 1450</em>, Bern 2024, S. 118–122, und ergänzende Auszüge von Diodor, Caesar und Felix Müller. Die Aufgaben des Dokuments wurden als Lernanregungen behandelt.</li><li><strong>PPP_Kelten (1).pptx:</strong> Einstieg über das Gallierbild und die Behauptung, Kelten seien nur Barbaren (Folien 3–4). Namen aus dem Klassen-Glücksrad und fremde Abbildungen werden nicht veröffentlicht.</li><li><strong><a href="${SRF}" target="_blank" rel="noopener">SRF: Die Kelten und die Römer</a></strong> (2024). Die Videoaufgaben wurden mit den deutschen SRF-Untertiteln abgeglichen. Video und Untertitel verbleiben bei SRF.</li><li><strong>Fachliche Präzisierung:</strong> <a href="https://hls-dhs-dss.ch/de/articles/008016/2007-07-30/" target="_blank" rel="noopener">Historisches Lexikon der Schweiz: Kelten</a> und <a href="https://hls-dhs-dss.ch/de/articles/008015/2014-02-19/" target="_blank" rel="noopener">Latènezeit</a>. Nicht alle keltischen Gruppen der heutigen Schweiz waren Helvetier. Fehlende eigene Geschichtsschreibung ist nicht mit fehlendem Schriftgebrauch gleichzusetzen.</li></ul><p>Alle Aufgaben und Wissenskarten sind neu formuliert. Unsichere Einzelangaben des Ausgangstexts zur Wanderungs- und Eroberungschronologie werden nicht als Quizfakten verwendet. Der Begriff «Hochkultur» wird als Diskussionsfrage behandelt.</p><p><strong>Speicherung:</strong> Das Spiel benötigt kein Konto. Antworten und Ausstellungstext bleiben in diesem Browser. Beim Öffnen des Videos oder externer Links gelten die Bedingungen des jeweiligen Anbieters.</p>`;
$('#sourcesBtn').onclick=()=>$('#sources').showModal();$('#closeSources').onclick=()=>$('#sources').close();
$('#reset').onclick=()=>{if(confirm('Alle Antworten und deinen Ausstellungstext in diesem Browser löschen und neu beginnen?')){state={station:0,task:0,results:{},draft:''};start(0);}};
order=current().items?.map((_,i)=>i)||[];render();
